/*!
 * Compatibility shim that exposes the old jquery.cookie API on top of js-cookie.
 *
 * Existing orchestrator code calls $.cookie("name") / $.cookie("name", "value", opts)
 * / $.removeCookie("name", opts). The original jquery.cookie 1.4.1 plugin is
 * deprecated and unmaintained; js-cookie 3.x replaces it. This shim keeps the
 * old call sites working without touching them.
 *
 * Load order matters: js-cookie.min.js must be loaded BEFORE this file, and
 * jQuery before both.
 */
(function ($, Cookies) {
    if (!$ || !Cookies) return;

    $.cookie = function (key, value, options) {
        if (arguments.length === 1) {
            return Cookies.get(key);
        }
        if (value === null || value === undefined) {
            Cookies.remove(key, options || {});
            return;
        }
        return Cookies.set(key, String(value), options || {});
    };

    $.removeCookie = function (key, options) {
        Cookies.remove(key, options || {});
        return true;
    };
})(window.jQuery, window.Cookies);
